cat > uiautomation/Tests/RoomReplyTests.swift <<'EOF'
import XCTest

final class RoomReplyTests: XCTestCase {
    func testReply() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        let room = app.staticTexts["Book Club"].firstMatch
        if room.waitForExistence(timeout: 5), !app.textViews.containing(NSPredicate(format: "label CONTAINS %@", "Loving it so far")).firstMatch.exists {
            room.tap()
        }
        let message = app.textViews.containing(NSPredicate(format: "label CONTAINS %@", "Loving it so far")).firstMatch
        XCTAssertTrue(message.waitForExistence(timeout: 10))
        message.press(forDuration: 1.2)
        sleep(2)
        print("CONTEXT_HIERARCHY_BEGIN\n\(app.debugDescription)\nCONTEXT_HIERARCHY_END")
    }
}
EOF
xcodebuild test -project uiautomation/SimulatorAutomation.xcodeproj -scheme NativeUIRunner -destination 'platform=iOS Simulator,id=7DC27F79-F3D5-4F9D-9E14-072770C6DEDB' -only-testing:UIAutomationTests/RoomReplyTests/testReply > uiautomation/test.log 2>&1

